"""Control requirements: start only from STOPPED and only when all listed
permissives are true. RUNNING may be entered only from STARTING. A stop
sequence may complete only after zero speed is confirmed."""

REQUIRED_START_PERMISSIVES = (
    "downstream_running",
    "sump_level_ok",
    "guard_closed",
    "estop_clear",
)

ALLOWED_TRANSITIONS = {
    "STOPPED": {"STARTING"},
    "STARTING": {"RUNNING", "STOPPING", "TRIPPED"},
    "RUNNING": {"STOPPING", "TRIPPED"},
    "STOPPING": {"STOPPED", "TRIPPED"},
    "TRIPPED": {"STOPPED"},
}

def transition(state, target):
    if target in ALLOWED_TRANSITIONS.get(state, set()):
        return target
    return state

def request_start(state, permissives):
    if state != "STOPPED":
        return state
    if not all(permissives.get(name, False) for name in REQUIRED_START_PERMISSIVES):
        return state
    return transition(state, "STARTING")

def confirm_running(state):
    return transition(state, "RUNNING")

def request_stop(state):
    return transition(state, "STOPPING")

def confirm_stopped(state, speed_zero):
    if state == "STOPPING" and speed_zero:
        return transition(state, "STOPPED")
    return state

ALLOWED_TRANSITIONS = {
    "STOPPED": {"STARTING"},
    "STARTING": {"RUNNING", "STOPPING", "TRIPPED"},
    "RUNNING": {"STOPPING", "TRIPPED"},
    "STOPPING": {"STOPPED", "TRIPPED"},
    "TRIPPED": {"STOPPED"},
}

def apply_operator_command(state, command):
    if command == "reset":
        if state == "TRIPPED":
            return "RUNNING"
        return state
    if command == "start" and state == "STOPPED":
        return "STARTING"
    return state
